-- Generated by schema/build.mjs from facet "health" v1. Do not edit.
-- One table per list (id TEXT PRIMARY KEY, columns, updated_at) plus an append-only
-- health_ops table: undo is a superseding op, nothing is rewritten in place.

CREATE TABLE IF NOT EXISTS health_allergies (
  id TEXT PRIMARY KEY,
  "substance" TEXT NOT NULL CHECK ("substance" IS NULL OR (length("substance") >= 1 AND length("substance") <= 120)),
  "reaction" TEXT CHECK ("reaction" IS NULL OR (length("reaction") >= 1 AND length("reaction") <= 200)),
  "severity" TEXT NOT NULL CHECK ("severity" IS NULL OR ("severity" IN ('Mild', 'Moderate', 'Severe'))),
  "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS health_medications (
  id TEXT PRIMARY KEY,
  "name" TEXT NOT NULL CHECK ("name" IS NULL OR (length("name") >= 1 AND length("name") <= 120)),
  "dose" TEXT CHECK ("dose" IS NULL OR (length("dose") >= 1 AND length("dose") <= 120)),
  "when" TEXT CHECK ("when" IS NULL OR (length("when") >= 1 AND length("when") <= 120)),
  "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS health_history (
  id TEXT PRIMARY KEY,
  "what" TEXT NOT NULL CHECK ("what" IS NULL OR (length("what") >= 1 AND length("what") <= 120)),
  "when" TEXT CHECK ("when" IS NULL OR (length("when") >= 1 AND length("when") <= 60)),
  "note" TEXT CHECK ("note" IS NULL OR (length("note") >= 1 AND length("note") <= 500)),
  "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS health_providers (
  id TEXT PRIMARY KEY,
  "role" TEXT NOT NULL CHECK ("role" IS NULL OR ("role" IN ('doctor', 'dentist', 'pharmacy', 'other'))),
  "name" TEXT NOT NULL CHECK ("name" IS NULL OR (length("name") >= 1 AND length("name") <= 120)),
  "contact" TEXT CHECK ("contact" IS NULL OR (length("contact") >= 1 AND length("contact") <= 200)),
  "next_visit" TEXT CHECK ("next_visit" IS NULL OR (length("next_visit") >= 1 AND length("next_visit") <= 60)),
  "notes" TEXT CHECK ("notes" IS NULL OR (length("notes") >= 1 AND length("notes") <= 500)),
  "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS health_insurance (
  id TEXT PRIMARY KEY,
  "plan_name" TEXT NOT NULL CHECK ("plan_name" IS NULL OR (length("plan_name") >= 1 AND length("plan_name") <= 120)),
  "renewal_date" TEXT CHECK ("renewal_date" IS NULL OR (length("renewal_date") >= 1 AND length("renewal_date") <= 60)),
  "notes" TEXT CHECK ("notes" IS NULL OR (length("notes") >= 1 AND length("notes") <= 500)),
  "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS health_ops (
  op_id TEXT PRIMARY KEY,
  receipt_id TEXT NOT NULL,
  op TEXT NOT NULL CHECK (op IN ('add', 'set', 'remove', 'undo')),
  list TEXT CHECK (list IS NULL OR list IN ('allergies', 'medications', 'history', 'providers', 'insurance')),
  item_id TEXT,
  value_json TEXT CHECK (value_json IS NULL OR json_valid(value_json)),
  at TEXT NOT NULL,
  supersedes TEXT REFERENCES health_ops (op_id)
);
CREATE INDEX IF NOT EXISTS health_ops_receipt ON health_ops (receipt_id);
